package dev.cardadvisor.ai;
import dev.cardadvisor.domain.Categories;import com.fasterxml.jackson.databind.*;import org.junit.jupiter.api.Test;import java.util.*;import java.nio.file.*;import static org.junit.jupiter.api.Assertions.*;
class CategoryEvaluationTest{
 @Test void reportSeparateSyntheticEvaluationWithoutAutomaticAdoption()throws Exception{
  var json=new ObjectMapper();var data=json.readTree(getClass().getResourceAsStream("/ai/category-evaluation.json"));assertEquals(120,data.size());var names=new HashSet<String>();var counts=new TreeMap<String,Integer>();var metrics=new TreeMap<String,Map<String,Object>>();int evaluated=0,correct=0,offered=0,correctOffered=0;
  for(var row:data){assertTrue(names.add(row.path("merchant").asText()));counts.merge(row.path("split").asText(),1,Integer::sum);var s=MerchantCategoryClassifier.classify(row.path("merchant").asText());assertTrue(Categories.ALL.contains(s.category()));assertTrue(s.features().stream().allMatch(f->f.matches("CATEGORY_HINT_[A-Z]+")));if(row.path("split").asText().equals("evaluation")){evaluated++;if(row.path("expected").asText().equals(s.category()))correct++;if(!s.category().equals("UNCLASSIFIED")){offered++;if(row.path("expected").asText().equals(s.category()))correctOffered++;}}}
  assertEquals(80,counts.get("development"));assertEquals(40,evaluated);double macro=0;
  for(String category:new TreeSet<>(Categories.ALL)){int tp=0,fp=0,fn=0,support=0;for(var row:data){if(!row.path("split").asText().equals("evaluation"))continue;String actual=row.path("expected").asText(),predicted=MerchantCategoryClassifier.classify(row.path("merchant").asText()).category();if(actual.equals(category))support++;if(actual.equals(category)&&predicted.equals(category))tp++;else if(predicted.equals(category))fp++;else if(actual.equals(category))fn++;}assertEquals(4,support);double precision=tp+fp==0?0:(double)tp/(tp+fp),recall=(double)tp/(tp+fn),f1=precision+recall==0?0:2*precision*recall/(precision+recall);macro+=f1;metrics.put(category,Map.of("support",support,"precision",precision,"recall",recall,"f1",f1));}
  var report=new LinkedHashMap<String,Object>();report.put("syntheticOnly",true);report.put("development",80);report.put("evaluation",40);report.put("macroF1",macro/10);report.put("accuracy",(double)correct/evaluated);report.put("suggestionPrecision",(double)correctOffered/offered);report.put("coverage",(double)offered/evaluated);report.put("automaticAdoption",false);report.put("categories",metrics);Files.createDirectories(Path.of("target/evaluation"));Files.writeString(Path.of("target/evaluation/categories.json"),json.writerWithDefaultPrettyPrinter().writeValueAsString(report));
 }
}
